{
  "units": [
    {
      "quote_ref": "F001",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Section heading for 29 CFR 1910.132, 'General requirements', containing no substantive operational requirements in itself."
    },
    {
      "quote_ref": "F002",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "Protective equipment—including personal protective equipment for eyes, face, head, and extremities, protective clothing, respiratory devices, and protective shields and barriers—must be provided, used, and maintained in a sanitary and reliable condition wherever necessary due to hazards of processes or environment, chemical hazards, radiological hazards, or mechanical irritants encountered in a manner capable of causing injury or impairment in the function of any part of the body through absorption, inhalation, or physical contact."
    },
    {
      "quote_ref": "F003",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "Where employees provide their own protective equipment, the employer is responsible for assuring its adequacy, including the proper maintenance and sanitation of that equipment."
    },
    {
      "quote_ref": "F004",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "All personal protective equipment must be of safe design and construction for the work to be performed."
    },
    {
      "quote_ref": "F005",
      "scope_refs": ["F024"],
      "kind": "requirement",
      "meaning": "For standards subject to paragraph (d) (§§ 1910.133, 1910.135, 1910.136, 1910.138, and 1910.140, but excluding §§ 1910.134 and 1910.137), the employer must assess the workplace to determine if hazards are present, or are likely to be present, which necessitate the use of personal protective equipment (PPE)."
    },
    {
      "quote_ref": "F006",
      "scope_refs": ["F005", "F024"],
      "kind": "requirement",
      "meaning": "If hazards necessitating PPE are present or likely to be present in the workplace assessed under paragraph (d), the employer must select, and have each affected employee use, the types of PPE that will protect the affected employee from the hazards identified in the hazard assessment."
    },
    {
      "quote_ref": "F007",
      "scope_refs": ["F005", "F024"],
      "kind": "requirement",
      "meaning": "If hazards necessitating PPE are present or likely to be present in the workplace assessed under paragraph (d), the employer must communicate selection decisions to each affected employee."
    },
    {
      "quote_ref": "F008",
      "scope_refs": ["F005", "F024"],
      "kind": "requirement",
      "meaning": "If hazards necessitating PPE are present or likely to be present in the workplace assessed under paragraph (d), the employer must select PPE that properly fits each affected employee."
    },
    {
      "quote_ref": "F010",
      "scope_refs": ["F005", "F009"],
      "kind": "statement",
      "meaning": "Non-mandatory appendix B provides an example of procedures that would comply with the requirement for a workplace hazard assessment."
    },
    {
      "quote_ref": "F011",
      "scope_refs": ["F005", "F024"],
      "kind": "requirement",
      "meaning": "The employer must verify that the required workplace hazard assessment has been performed through a written certification that identifies the workplace evaluated, the person certifying that the evaluation has been performed, the date(s) of the hazard assessment, and identifies the document as a certification of hazard assessment."
    },
    {
      "quote_ref": "F012",
      "scope_refs": [],
      "kind": "prohibition",
      "meaning": "Defective or damaged personal protective equipment must not be used."
    },
    {
      "quote_ref": "F013:F018",
      "scope_refs": ["F024"],
      "kind": "requirement",
      "meaning": "For standards subject to paragraph (f) (§§ 1910.133, 1910.135, 1910.136, 1910.138, and 1910.140, but excluding §§ 1910.134 and 1910.137), the employer must provide training to each employee required by 29 CFR 1910.132 to use PPE, ensuring each such employee is trained to know at least: when PPE is necessary; what PPE is necessary; how to properly don, doff, adjust, and wear PPE; the limitations of the PPE; and the proper care, maintenance, useful life, and disposal of the PPE."
    },
    {
      "quote_ref": "F019",
      "scope_refs": ["F013", "F024"],
      "kind": "condition",
      "meaning": "Before being allowed to perform work requiring the use of PPE under covered standards, each affected employee must demonstrate an understanding of the training specified in paragraph (f)(1) and the ability to use PPE properly."
    },
    {
      "quote_ref": "F020",
      "scope_refs": ["F013", "F019", "F024"],
      "kind": "requirement",
      "meaning": "When the employer has reason to believe that any affected employee who has already been trained does not have the understanding and skill required by paragraph (f)(2), the employer must retrain each such employee."
    },
    {
      "quote_ref": "F021",
      "scope_refs": ["F020", "F024"],
      "kind": "condition",
      "meaning": "Circumstances requiring employee retraining include, but are not limited to, situations where changes in the workplace render previous PPE training obsolete."
    },
    {
      "quote_ref": "F022",
      "scope_refs": ["F020", "F024"],
      "kind": "condition",
      "meaning": "Circumstances requiring employee retraining include, but are not limited to, situations where changes in the types of PPE to be used render previous training obsolete."
    },
    {
      "quote_ref": "F023",
      "scope_refs": ["F020", "F024"],
      "kind": "condition",
      "meaning": "Circumstances requiring employee retraining include, but are not limited to, situations where inadequacies in an affected employee's knowledge or use of assigned PPE indicate that the employee has not retained the requisite understanding or skill."
    },
    {
      "quote_ref": "F024",
      "scope_refs": [],
      "kind": "statement",
      "meaning": "Paragraphs (d) (hazard assessment and equipment selection) and (f) (training) of 29 CFR 1910.132 apply only to §§ 1910.133, 1910.135, 1910.136, 1910.138, and 1910.140, and do not apply to §§ 1910.134 and 1910.137."
    },
    {
      "quote_ref": "F025",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "Except as provided in paragraphs (h)(2) through (h)(6) of this section, protective equipment, including personal protective equipment (PPE), used to comply with 29 CFR part 1910 must be provided by the employer at no cost to employees."
    },
    {
      "quote_ref": "F026",
      "scope_refs": ["F025"],
      "kind": "exemption",
      "meaning": "The employer is not required to pay for non-specialty safety-toe protective footwear (including steel-toe shoes or steel-toe boots) and non-specialty prescription safety eyewear, provided that the employer permits such items to be worn off the job-site."
    },
    {
      "quote_ref": "F027",
      "scope_refs": ["F025"],
      "kind": "exemption",
      "meaning": "When the employer provides metatarsal guards and allows an employee, at the employee's request, to use shoes or boots with built-in metatarsal protection, the employer is not required to reimburse the employee for the shoes or boots."
    },
    {
      "quote_ref": "F028:F029",
      "scope_refs": ["F025"],
      "kind": "exemption",
      "meaning": "The employer is not required to pay for the logging boots required by 29 CFR 1910.266(d)(1)(v)."
    },
    {
      "quote_ref": "F028:F030",
      "scope_refs": ["F025"],
      "kind": "exemption",
      "meaning": "The employer is not required to pay for everyday clothing, such as long-sleeve shirts, long pants, street shoes, and normal work boots."
    },
    {
      "quote_ref": "F028:F031",
      "scope_refs": ["F025"],
      "kind": "exemption",
      "meaning": "The employer is not required to pay for ordinary clothing, skin creams, or other items used solely for protection from weather, such as winter coats, jackets, gloves, parkas, rubber boots, hats, raincoats, ordinary sunglasses, and sunscreen."
    },
    {
      "quote_ref": "F032",
      "scope_refs": ["F025"],
      "kind": "requirement",
      "meaning": "The employer must pay for replacement PPE, except when the employee has lost or intentionally damaged the PPE."
    },
    {
      "quote_ref": "F033",
      "scope_refs": ["F003", "F025"],
      "kind": "permission",
      "meaning": "Where an employee provides adequate protective equipment they own pursuant to paragraph (b), the employer may allow the employee to use it and is not required to reimburse the employee for that equipment."
    },
    {
      "quote_ref": "F033",
      "scope_refs": ["F025"],
      "kind": "prohibition",
      "meaning": "The employer must not require an employee to provide or pay for their own PPE, unless the PPE is excepted by paragraphs (h)(2) through (h)(5) of this section."
    },
    {
      "quote_ref": "F034",
      "scope_refs": ["F025"],
      "kind": "requirement",
      "meaning": "Paragraph (h) became effective on February 13, 2008, and employers were required to implement the PPE payment requirements no later than May 15, 2008."
    },
    {
      "quote_ref": "F036",
      "scope_refs": ["F025", "F035"],
      "kind": "statement",
      "meaning": "When the provisions of another OSHA standard specify whether or not the employer must pay for specific equipment, the payment provisions of that other standard prevail over § 1910.132(h)."
    },
    {
      "quote_ref": "F037",
      "scope_refs": [],
      "kind": "background",
      "meaning": "Federal Register citation and rulemaking history note, conveying no substantive workplace safety obligations."
    }
  ]
}
